/**
 * Motion39 — "UNITED KINGDOM · DIGITAL INFRASTRUCTURE GRID"
 * 1920x1080 · 60 fps · 1440 frames (24 s) · PERFECT LOOP
 *
 * Peta TIDAK langsung jadi: terbentuk memancar dari London, lalu kamera
 * bergerak menerus (yaw + pitch + dolly, satu siklus penuh per loop → seam
 * nol). Teks sengaja minim supaya pembeli bisa menimpa teksnya sendiri.
 *
 * Geometri: Natural Earth (DOMAIN PUBLIK) via nvkelso/natural-earth-vector.
 *   - garis negara  : ne_10m_admin_0_countries (Britania Raya + Irlandia
 *                     Utara + Hebrides, Orkney, Anglesey, Wight)
 *   - batas wilayah : ne_10m_admin_1_states_provinces
 *   - kota          : ne_10m_populated_places_simple
 *
 * PROYEKSI: Transverse Mercator dengan parameter British National Grid
 * (OSGB36) — meridian tengah 2 BB, lintang asal 49 LU, faktor skala
 * 0,9996012717. Inilah proyeksi resmi Ordnance Survey, dan keluarga proyeksi
 * yang belum dipakai di seri ini (sebelumnya Mercator, Lambert kerucut,
 * Albers, LAEA). Memang paling tepat untuk negara yang sempit membujur
 * utara-selatan: silindernya diputar sehingga garis singgungnya membentang
 * utara-selatan tepat di tengah negara. Diuji: 1 derajat lintang terukur
 * 111,2 km di 54 LU (benar 111,2) dan 1 derajat bujur 65,3 km (benar 65,4).
 *
 * SISIPAN SHETLAND. Shetland ada ~250 km di utara daratan Skotlandia, dan
 * seperti hampir semua peta Britania kepulauan itu dipindahkan ke SISIPAN.
 * Dua alasan: ruang di antaranya laut kosong, dan Shetland sendirian
 * menambah 14,1% tinggi bbox. Berbeda dari sisipan Canarias pada versi
 * Spanyol, di sini TIDAK perlu proyeksi kedua — Shetland cuma 1 derajat dari
 * meridian tengah OSGB sehingga distorsi TM di sana dapat diabaikan; bloknya
 * cukup DIGESER. Kotaknya ditaruh di Laut Utara, timur laut Skotlandia, yang
 * sudah berada DI DALAM bbox peta (Inggris menjulur ke timur sampai lon 1,8
 * di lintang 52-53) — jadi sisipannya benar-benar gratis: menghemat tinggi
 * tanpa menambah lebar sedikit pun. Bingkainya digambar di ruang peta
 * sehingga ikut miring bersama kamera.
 *
 * EMPAT NEGARA KONSTITUEN, BUKAN 232 DISTRIK. Natural Earth memberi 232 unit
 * admin-1 (borough, distrik, unitary authority) yang jadi bubur kalau
 * digambar. Unit-unit itu DILEBUR memakai field geonunit menjadi England,
 * Scotland, Wales, dan Northern Ireland lewat pembatalan sisi bersama —
 * terukur 60,0% dari 19.965 sisi terbatalkan, tanda topologi berkas itu
 * sangat bersih. Hasilnya hanya DUA garis batas darat di dalam peta
 * (Skotlandia-Inggris dan Wales-Inggris), persis pembagian yang bermakna
 * bagi penonton. Batas Irlandia Utara sudah termuat di garis negara karena
 * itu batas internasional dengan Republik Irlandia.
 *
 * Batas iterasi grid titik DIHITUNG dari bbox, bukan angka tetap.
 */
import React, {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  random,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';
import {noise3D} from '@remotion/noise';

/* ═══════════════════════════════════════════════════════════ FONT */

const FONT_CSS = `
@font-face{font-family:'MxMono39';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;font-display:block;}
@font-face{font-family:'MxTitle39';src:url(data:font/woff2;base64,) format('woff2');font-weight:700;font-style:normal;font-display:block;}
`;

let fontsPromise: Promise<unknown> | null = null;
const ensureFonts = () => {
  if (fontsPromise) return fontsPromise;
  const st = document.createElement('style');
  st.textContent = FONT_CSS;
  document.head.appendChild(st);
  fontsPromise = Promise.all([
    (document as any).fonts.load("400 24px 'MxMono39'"),
    (document as any).fonts.load("700 24px 'MxTitle39'"),
  ]).catch(() => null);
  return fontsPromise;
};

const useEmbeddedFonts = () => {
  const [handle] = useState(() => delayRender('fonts-motion39'));
  const [ready, setReady] = useState(false);
  useEffect(() => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      setReady(true);
      continueRender(handle);
    };
    const to = setTimeout(finish, 2500);
    ensureFonts().then(finish, finish);
    return () => clearTimeout(to);
  }, [handle]);
  return ready;
};

/* ═══════════════════════════════════════════════════════ KONSTANTA */

const W = 1920;
const H = 1080;
const DUR_F = 1440;
const DUR = DUR_F / 60;

