// bahkan lebih sempit dari Jerman. Yang membatasi murni tinggi peta; kolom
// kota tidak ikut membatasi karena London ada jauh di selatan. Diuji 72 pose
// kamera pada MAPK 0,98: peta 75..1019 px vertikal dan 690..1352 px
// horizontal. Peta digeser 40 px ke kanan sehingga sepertiga kiri frame jadi
// area bersih yang lega untuk teks pembeli — pada subjek sesempit ini itu
// nilai jual, bukan ruang terbuang. Puncak peta (Skotlandia utara/Orkney)
// jatuh di x=837-997 px, aman dari blok judul yang berakhir di x=700.
const CXS = W / 2 + 40;
const CYS = H / 2 - 26;

